      appears: [{ id: 'jim', name: 'Jim Hawkins' }, { id: 'smollett', name: 'Captain Smollett' }, { id: 'trelawney', name: 'Squire Trelawney' }, { id: 'livesey', name: 'Dr. Livesey' }, { id: 'silver', name: 'Long John Silver' }],
      themes: [{ slug: 'jim-alone', label: 'The boy who acts alone' }],
